/* Token Radar — a dark, precision instrument for finding pre-token launch candidates.
   Palette: deep space navy, warm amber for value, teal for growth, coral for decline.
   Type: system UI for prose, ui-monospace for every number. */

:root {
  --bg: #0a0d13;
  --bg-2: #0e1219;
  --panel: #12161f;
  --panel-2: #171c27;
  --line: #222a38;
  --line-soft: #1a2130;
  --ink: #e5e9f2;
  --ink-dim: #9aa3b5;
  --ink-faint: #677083;
  --amber: #ffb454;
  --amber-deep: #c98a35;
  --teal: #4ad3c3;
  --coral: #ff6b6e;
  --violet: #a78bfa;
  --up: #4ad3c3;
  --down: #ff6b6e;
  --rad: 10px;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  --ui: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  background:
    radial-gradient(1100px 480px at 82% -10%, rgba(255, 180, 84, 0.07), transparent 60%),
    radial-gradient(900px 420px at 8% -12%, rgba(74, 211, 195, 0.06), transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: var(--ui);
  font-size: 14px;
  line-height: 1.45;
  min-height: 100vh;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  margin: -1px; padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ------------------------------- header ------------------------------- */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 28px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), transparent);
}

.brand { display: flex; align-items: center; gap: 16px; }

.radar-mark {
  position: relative;
  width: 46px; height: 46px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background:
    radial-gradient(circle, transparent 29%, var(--line-soft) 30%, transparent 31%),
    radial-gradient(circle, transparent 57%, var(--line-soft) 58%, transparent 59%),
    linear-gradient(90deg, transparent 49%, var(--line-soft) 50%, transparent 51%),
    linear-gradient(0deg, transparent 49%, var(--line-soft) 50%, transparent 51%),
    var(--panel);
  flex: none;
  overflow: hidden;
}

.radar-mark::before {
  content: "";
  position: absolute;
  inset: 7px;
  border-radius: 50%;
  background: repeating-conic-gradient(from 0deg, transparent 0deg 10deg, rgba(255, 180, 84, 0.05) 10deg 20deg);
}

.sweep {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(from 0deg, rgba(255, 180, 84, 0.55), rgba(255, 180, 84, 0) 70deg);
  animation: sweep 4.5s linear infinite;
  transform-origin: 50% 50%;
}

@keyframes sweep {
  to { transform: rotate(360deg); }
}

.brand-text h1 {
  margin: 0;
  font-size: 21px;
  letter-spacing: 0.06em;
  font-weight: 700;
}

.brand-text .tagline {
  margin: 2px 0 0;
  color: var(--ink-faint);
  font-size: 12px;
  letter-spacing: 0.02em;
}

.stats {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink-dim);
  font-size: 12px;
  font-family: var(--mono);
  white-space: nowrap;
}

.chip b { color: var(--ink); font-weight: 600; }

.chip .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--amber); }

.chip.teal .dot { background: var(--teal); }

.chip.violet .dot { background: var(--violet); }

/* ------------------------------- toolbar ------------------------------ */

.toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 28px;
  position: sticky;
  top: 0;
  z-index: 5;
  background: rgba(10, 13, 19, 0.92);
  backdrop-filter: blur(6px);
  border-bottom: 1px solid var(--line);
}

.search { flex: 1 1 320px; max-width: 460px; }

.search input {
  width: 100%;
  padding: 9px 14px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink);
  font-size: 13px;
  font-family: var(--ui);
  outline: none;
}

.search input:focus { border-color: var(--amber-deep); box-shadow: 0 0 0 3px rgba(255, 180, 84, 0.12); }

.search input::placeholder { color: var(--ink-faint); }

.field select {
  padding: 9px 30px 9px 12px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink);
  font-size: 13px;
  font-family: var(--ui);
  outline: none;
  cursor: pointer;
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--ink-faint) 50%), linear-gradient(135deg, var(--ink-faint) 50%, transparent 50%);
  background-position: calc(100% - 16px) 55%, calc(100% - 11px) 55%;
  background-size: 5px 5px;
  background-repeat: no-repeat;
}

.field select:focus { border-color: var(--amber-deep); }

.count {
  margin-left: auto;
  color: var(--ink-faint);
  font-size: 12px;
  font-family: var(--mono);
  white-space: nowrap;
}

/* small secondary actions: toolbar export and drawer copy */

.export,
.ghost-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink-dim);
  font-size: 12.5px;
  font-family: var(--ui);
  cursor: pointer;
  white-space: nowrap;
  transition: color 0.12s ease, border-color 0.12s ease;
}

.export:hover,
.ghost-btn:hover {
  color: var(--amber);
  border-color: var(--amber-deep);
}

.export:focus-visible,
.ghost-btn:focus-visible {
  outline: 2px solid var(--amber-deep);
  outline-offset: 2px;
}

.section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: 16px 0 6px;
}

.section-head .section-title { margin: 0; }

.section-head .ghost-btn { padding: 4px 10px; font-size: 11.5px; }

/* -------------------------------- board ------------------------------- */

.board-wrap {
  margin: 0 18px;
  border: 1px solid var(--line);
  border-radius: var(--rad);
  overflow: hidden;
  background: var(--panel);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.25);
}

.board {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.board thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--panel-2);
  color: var(--ink-dim);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}

.board thead th.num { text-align: right; }

.board thead th:hover { color: var(--amber); }

.board thead th .arr { color: var(--amber); margin-left: 4px; font-size: 10px; }

.board tbody td {
  padding: 8px 12px;
  border-bottom: 1px solid var(--line-soft);
  vertical-align: middle;
}

.board tbody tr { cursor: pointer; transition: background 0.12s ease; }

.board tbody tr:hover { background: rgba(255, 180, 84, 0.05); }

.board tbody tr:last-child td { border-bottom: none; }

.board td.num { text-align: right; font-family: var(--mono); font-variant-numeric: tabular-nums; }

.rank {
  color: var(--ink-faint);
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
}

.rank.top {
  color: var(--amber);
  font-weight: 700;
}

.cell-name { min-width: 210px; }

.name-line { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

.name-line .pname { font-weight: 600; color: var(--ink); }

.name-line .slug { color: var(--ink-faint); font-family: var(--mono); font-size: 11px; }

.tag {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  border: 1px solid var(--line);
  color: var(--ink-dim);
  text-transform: uppercase;
}

.tag.watch { color: var(--amber); border-color: rgba(255, 180, 84, 0.4); }

.tag.early { color: var(--teal); border-color: rgba(74, 211, 195, 0.35); }

.val {
  color: var(--amber);
  font-weight: 700;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
}

.tvl { color: var(--ink); }

.chg { font-family: var(--mono); font-variant-numeric: tabular-nums; font-weight: 600; }

.chg.up { color: var(--up); }

.chg.down { color: var(--down); }

.chg.flat { color: var(--ink-faint); }

.age-cell { color: var(--ink-dim); }

.chains-cell { color: var(--ink-dim); font-family: var(--mono); font-size: 11px; }

.badge-col { width: 84px; text-align: right; }

.empty {
  padding: 46px 20px;
  text-align: center;
  color: var(--ink-faint);
  font-size: 13px;
}

/* -------------------------------- live -------------------------------- */

.live {
  margin: 26px 18px 8px;
  padding: 16px 18px;
  border: 1px dashed var(--line);
  border-radius: var(--rad);
  background: rgba(18, 22, 31, 0.55);
}

.live h2 {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.live-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }

.live-table th {
  text-align: left;
  color: var(--ink-faint);
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 6px 10px;
  border-bottom: 1px solid var(--line-soft);
}

.live-table th.num, .live-table td.num { text-align: right; }

.live-table td {
  padding: 6px 10px;
  border-bottom: 1px solid var(--line-soft);
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  color: var(--ink-dim);
}

.live-table tr:last-child td { border-bottom: none; }

.live-table .pname { font-family: var(--ui); color: var(--ink); font-weight: 600; }

/* --------------------------------- foot ------------------------------- */

.foot { padding: 18px 28px 26px; color: var(--ink-faint); font-size: 11.5px; }

.foot p { margin: 0; }

/* -------------------------------- drawer ------------------------------ */

.backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 6, 10, 0.55);
  z-index: 20;
}

.drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 480px;
  max-width: 94vw;
  z-index: 21;
  background: var(--panel);
  border-left: 1px solid var(--line);
  box-shadow: var(--shadow);
  overflow-y: auto;
  padding: 18px 20px 32px;
  transition: transform 0.24s ease;
}

body.no-anim .drawer { transition: none; }

.drawer-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }

.drawer-head h2 { margin: 0; font-size: 20px; letter-spacing: 0.01em; }

.drawer-head .close {
  background: none;
  border: 1px solid var(--line);
  color: var(--ink-dim);
  width: 30px; height: 30px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 15px;
  line-height: 1;
  flex: none;
}

.drawer-head .close:hover { color: var(--ink); border-color: var(--amber-deep); }

.drawer .slugline { margin: 6px 0 0; color: var(--ink-faint); font-family: var(--mono); font-size: 12px; }

.drawer .tagrow { margin: 10px 0 0; display: flex; gap: 8px; flex-wrap: wrap; }

.kv {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 14px 0 4px;
}

.kv .cell {
  background: var(--bg-2);
  border: 1px solid var(--line-soft);
  border-radius: 9px;
  padding: 8px 10px;
}

.kv .k { font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.07em; color: var(--ink-faint); }

.kv .v { font-family: var(--mono); font-variant-numeric: tabular-nums; color: var(--ink); font-size: 15px; margin-top: 3px; }

.kv .v.amber { color: var(--amber); }

.section-title {
  margin: 16px 0 6px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-dim);
}

.math {
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--bg-2);
  overflow: hidden;
}

.math-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 7px 12px;
  border-bottom: 1px solid var(--line-soft);
  font-size: 12.5px;
}

.math-row:last-child { border-bottom: none; }

.math-row .formula { color: var(--ink-dim); }

.math-row .formula .mono { color: var(--ink-faint); font-family: var(--mono); font-size: 11.5px; }

.math-row .answer { font-family: var(--mono); font-variant-numeric: tabular-nums; color: var(--ink); white-space: nowrap; }

.math-row.total { background: rgba(255, 180, 84, 0.07); }

.math-row.total .answer { color: var(--amber); font-weight: 700; font-size: 14px; }

.math-row.total .formula { color: var(--ink); font-weight: 600; }

.plan { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }

.plan li {
  border: 1px solid var(--line-soft);
  border-radius: 9px;
  background: var(--bg-2);
  padding: 9px 12px;
  font-size: 12.6px;
  color: var(--ink);
}

.plan .step-no {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 19px; height: 19px;
  border-radius: 6px;
  background: rgba(255, 180, 84, 0.14);
  color: var(--amber);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  margin-right: 8px;
}

.plan .cost {
  display: block;
  margin-top: 5px;
  color: var(--teal);
  font-size: 11.5px;
}

.notice {
  margin-top: 16px;
  padding: 10px 12px;
  border-radius: 9px;
  border: 1px solid rgba(167, 139, 250, 0.3);
  background: rgba(167, 139, 250, 0.07);
  color: var(--ink-dim);
  font-size: 11.5px;
}

/* ------------------------------ responsive ---------------------------- */

@media (max-width: 1100px) {
  .toolbar { flex-wrap: wrap; }
  .count { margin-left: 0; }
}

@media (max-width: 760px) {
  .topbar { flex-direction: column; align-items: flex-start; }
  .stats { justify-content: flex-start; }
  .cell-name { min-width: 140px; }
  .board-wrap { margin: 0 8px; overflow-x: auto; }
  .board { min-width: 760px; }
}
